function applyLang(lang) {
  const dict = I18N[lang] || I18N.cs;
  document.documentElement.lang = lang;
  for (const el of document.querySelectorAll("[data-i18n]")) {
    const key = el.getAttribute("data-i18n");
    const value = dict[key];
    if (typeof value === "string") el.textContent = value;
  }
  for (const btn of document.querySelectorAll(".lang__btn")) {
    const pressed = btn.getAttribute("data-lang") === lang;
    btn.setAttribute("aria-pressed", pressed ? "true" : "false");
  }
  try {
    localStorage.setItem("noblelift_lang", lang);
  } catch {}
}

document.getElementById("y").textContent = String(new Date().getFullYear());

const saved = (() => {
  try {
    return localStorage.getItem("noblelift_lang");
  } catch {
    return null;
  }
})();
applyLang(saved === "en" ? "en" : "cs");

for (const btn of document.querySelectorAll(".lang__btn")) {
  btn.addEventListener("click", () => applyLang(btn.getAttribute("data-lang")));
}

